import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import {
  THOUGHTSPOT_CADENCES_LIVEBOARD_ID,
  TOP_HEADER_PX,
  LIVEBOARD_DARK_CUSTOMIZATIONS,
} from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BG      = '#FFFFFF';
const NAVY    = '#071331';
const LABEL   = 'rgba(0,0,0,0.45)';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 170px)`;

const TABS = [
  { id: 'tab1', label: 'Overview',  tabId: '3e32920c-eda4-48b0-aee5-96c807c8912c' },
  { id: 'tab2', label: 'Trends',    tabId: '4fb7f49f-406b-45f7-af0a-9002d2ae0486' },
];

export default function CadencesPage() {
  const { hiddenActions, disabledActions } = useTier();
  const [selectedTab, setSelectedTab] = useState('tab1');
  const active = TABS.find(t => t.id === selectedTab)!;

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot – Cadences]', formatThoughtSpotEmbedError(err), err);
  }, []);

  return (
    <div style={{ backgroundColor: BG, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* Page header */}
      <div style={{ padding: '1.75rem 2.5rem 1rem' }}>
        <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: LABEL, marginBottom: 6 }}>
          xSuite
        </div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: NAVY, margin: '0 0 1rem', letterSpacing: '-0.03em' }}>
          Cadences
        </h1>

        {/* Tab switcher pills */}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {TABS.map(tab => {
            const isActive = tab.id === selectedTab;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setSelectedTab(tab.id)}
                style={{
                  padding: '7px 20px',
                  borderRadius: 6,
                  border: `1px solid ${isActive ? '#1E5DEB' : 'rgba(0,0,0,0.15)'}`,
                  background: isActive ? '#1E5DEB' : '#FFFFFF',
                  color: isActive ? '#FFFFFF' : 'rgba(17,17,17,0.70)',
                  fontSize: 13.5,
                  fontWeight: isActive ? 600 : 400,
                  cursor: 'pointer',
                  transition: 'all 0.15s ease',
                  whiteSpace: 'nowrap',
                  letterSpacing: '-0.01em',
                }}
              >
                {tab.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Embed */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div style={{
          backgroundColor: '#FFFFFF',
          borderRadius: 10,
          overflow: 'visible',
          minHeight: EMBED_MIN_H,
          border: '1px solid rgba(30,93,235,0.10)',
        }}>
          <LiveboardEmbed
            key={active.tabId}
            liveboardId={THOUGHTSPOT_CADENCES_LIVEBOARD_ID}
            activeTabId={active.tabId}
            fullHeight
            hideTabPanel
            isLiveboardStylingAndGroupingEnabled
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            customizations={LIVEBOARD_DARK_CUSTOMIZATIONS}
            onError={onError}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
